### 1.10 UnityUpComponent - 组件基类

**文件位置**: `assets/Script/Base/UnityUpComponent.ts`

**功能说明**:
所有需要update的组件基类，支持全局暂停。

**使用示例**:
```typescript
import { UnityUpComponent } from './Base/UnityUpComponent';

export class MyComponent extends UnityUpComponent {
    protected _update(dt: number): void {
        // 这里的更新逻辑会受UnityUpComponent.isStop控制
        this.position += this.speed * dt;
    }
}

// 全局暂停所有更新
UnityUpComponent.isStop = true;

// 恢复
UnityUpComponent.isStop = false;
```

