```

**使用示例**:
```typescript
import L18nManager from './Base/TextAdaptation/L18Manager';
import { LanguageType } from './Base/TextAdaptation/L18Manager';

// 1. 获取当前语言
const currentLang = L18nManager.instance.lang;
