collector.attackR = 100;  // 攻击范围100

// 2. 获取最近的目标
const nearestTarget = collector.singleTarget;
if (nearestTarget && !nearestTarget.isDie) {
    console.log('最近目标：', nearestTarget.node.name);
    nearestTarget.Hit(30);
}

// 3. 获取范围内所有目标
const allTargets = collector.groupTarget;
if (allTargets && allTargets.length > 0) {
    console.log('范围内有', allTargets.length, '个敌人');
    allTargets.forEach(target => {
