// 1. 播放击中特效
EffectManager.instance.addShowEffect(
    new Vec3(100, 50, 0),
    EffectEnum.hit,
    1.0
);

// 2. 播放爆炸特效
EffectManager.instance.addShowEffect(
    enemyPos,
    EffectEnum.explosion,
    2.0  // 放大2倍
);

// 3. 每帧调用（在update中）
update(dt: number) {
    EffectManager.instance.frameReleaseSpecialEffects();
}

// 特效特点：
// - 防重复：相同位置0.5单位内不重复播放
// - 分帧处理：每帧处理5个特效，避免卡顿
